//! 🧪️ Portable paragraph geometry matches independent OpenType metrics and closes every partial child under original demands.
use super::*;
use semio_framework_2d_text_font::{FontFaceAdmissionJob,FontOutlineLimits};
use semio_framework_2d_text_font_testing::{bytes,close};
use semio_framework_2d_text_font_shape_unicode::{UnicodeDataAdmissionJob,UNICODE_BYTES};
#[path="🧵️flow/🦀️.rs"]
mod flow;

#[test]
fn paragraphs_match_portable_opentype_placement_and_grants(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 let mut unicode_job=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while !unicode_job.advance(4096,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let unicode=unicode_job.take_result().unwrap();
 let mut font_job=FontFaceAdmissionJob::new(bytes(fixture["font"].as_str().unwrap()),FontOutlineLimits::default());while !font_job.advance(4096,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let fonts=[font_job.take_result().unwrap()];
 let mut line_job=semio_framework_2d_text_font_shape_unicode::line_break::LineBreakDataAdmissionJob::new(semio_framework_2d_text_font_shape_unicode::line_break::LINE_BREAK_BYTES.to_vec(),1000000);while !line_job.advance(7,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(7))).unwrap().done{}let line_data=line_job.take_result().unwrap();
 let oracle=ttf_parser::Face::parse(&fonts[0].source,0).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let text=row["text"].as_str().unwrap();let spans=row["spans"].as_array().unwrap().iter().map(|span|FontRunSpan{start:span["start"].as_u64().unwrap()as usize,end:span["end"].as_u64().unwrap()as usize,size:span["size"].as_f64().unwrap(),tracking:span["tracking"].as_f64().unwrap(),face:span["face"].as_u64().unwrap()as usize}).collect::<Vec<_>>();let style=ParagraphStyle{width:row["width"].as_f64().unwrap(),origin:[0.0;2],size:row["size"].as_f64().unwrap(),line_height:row["lineHeight"].as_f64().unwrap(),tracking:row["tracking"].as_f64().unwrap(),alignment:match row["alignment"].as_str().unwrap(){"center"=>ParagraphAlignment::Center,"right"=>ParagraphAlignment::Right,"justify"=>ParagraphAlignment::Justify,_=>ParagraphAlignment::Left}};
  for grant in [1,7,4096]{let mut cursor=FontParagraphCursor::new(text,1,style,&spans,FontOutlineLimits::default(),unicode.layout,line_data.layout);let mut work=0;loop{let progress=cursor.advance(text,&fonts,&spans,&unicode.source,&line_data.source,grant,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(grant))).unwrap();assert!(progress.work-work<=grant as u64);work=progress.work;if progress.done{break;}assert!(cursor.result().is_err());}let output=cursor.take_result().unwrap();let lines=output.lines.iter().map(|line|&text[line.start..line.end]).collect::<Vec<_>>();assert_eq!(lines,row["expectedLines"].as_array().unwrap().iter().map(|value|value.as_str().unwrap()).collect::<Vec<_>>(),"{}",row["name"]);let expected=row["expectedGlyphs"].as_array().unwrap();assert_eq!(output.glyphs.len(),expected.len());for(actual,expected)in output.glyphs.iter().zip(expected){assert_eq!(u64::from(actual.glyph),expected["glyph"].as_u64().unwrap());assert_eq!(actual.source_at,expected["sourceAt"].as_u64().unwrap()as usize);assert_eq!(actual.size,expected["size"].as_f64().unwrap());assert_eq!(actual.style,expected["style"].as_u64().map(|value|value as usize));for axis in 0..2{assert!((actual.origin[axis]-expected["origin"][axis].as_f64().unwrap()).abs()<1e-8,"{}",row["name"]);}let advance=f64::from(oracle.glyph_hor_advance(ttf_parser::GlyphId(actual.glyph)).unwrap())*actual.size/f64::from(fonts[0].face.units_per_em);assert!((actual.advance-advance).abs()<1e-8);}close(cursor);close(output);}
  for stop in [0,1,7,100,1000]{let mut cursor=FontParagraphCursor::new(text,1,style,&spans,FontOutlineLimits::default(),unicode.layout,line_data.layout);if stop>0{cursor.advance(text,&fonts,&spans,&unicode.source,&line_data.source,stop,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(stop))).unwrap();}cursor.cancel();assert!(cursor.result().is_err());close(cursor);}close(spans);
 }
 close(font_job);let [font]=fonts;close(font);close(line_job);close(line_data);close(unicode_job);close(unicode);
}
